import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"第四部：实践与恢复","description":"让学习和改变进入真实日程，通过第一周实践、容量设计与可回归节律，使行动能够承受忙碌、中断和低谷。","frontmatter":{"title":"第四部：实践与恢复","description":"让学习和改变进入真实日程，通过第一周实践、容量设计与可回归节律，使行动能够承受忙碌、中断和低谷。","updated":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-4/practice-and-recovery.md","filePath":"threads/part-4/practice-and-recovery.md","lastUpdated":1788307200000}'),i={name:"threads/part-4/practice-and-recovery.md"};function l(o,t,h,n,p,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第四部-实践与恢复" tabindex="-1">第四部：实践与恢复 <a class="header-anchor" href="#第四部-实践与恢复" aria-label="Permalink to &quot;第四部：实践与恢复&quot;">​</a></h1><p>计划写在纸上时，几乎总是比生活整齐。</p><p>纸上没有临时电话，没有睡不好的夜晚，没有需要照顾的人，也没有某个下午突然消失的力气。它只知道目标、日期和一条看起来会一直向前的线。可真正的改变，必须进入这些不整齐的日子，才知道自己是否站得住。</p><p>这一部不再增加新的宏大目标。它把前面学到的能力、故事、工具和证据放进一周、一日和一次中断里。我们会观察：什么条件让行动容易开始，什么代价正在被隐藏，容量下降时怎样减轻重量，停下来之后怎样知道从哪里回来。</p><p>可靠的系统不是永远不断。它是在断裂发生之后，不需要先羞辱自己，就仍然留着一条回来的路。</p><h2 id="本部要回答的问题" tabindex="-1">本部要回答的问题 <a class="header-anchor" href="#本部要回答的问题" aria-label="Permalink to &quot;本部要回答的问题&quot;">​</a></h2><ul><li>第一周怎样留下基线、反馈、延迟复测和一次迁移，而不是只留下连续打卡？</li><li>怎样为完整日、压缩日和恢复日准备不同重量的动作？</li><li>时间、精力、关系和身体如何一起进入预算？</li><li>哪些事情会真正复利，哪些重复只是在积累疲惫？</li><li>中断之后，怎样用一个足够小的动作恢复节律，而不是补偿性透支？</li><li>当学习者尚未成年，孩子、家长、教师与 AI 怎样分工，既提供保护又不夺走主体性？</li></ul><p>这里的“恢复”不是要求你尽快恢复生产力。安全、饮食、睡眠、求助和基本照料本身就可以是当天最重要的工作。</p><h2 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to &quot;阅读路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>章节</th><th>要留下的东西</th></tr></thead><tbody><tr><td>先过一周</td><td><a href="./week-1">实践篇：先把第一周过完</a></td><td>起点、七天证据链和周末决定</td></tr><tr><td>家庭共同学习（按需）</td><td><a href="./family-learning">家庭学习篇：把成长还给孩子</a></td><td>一项由孩子参与定义的任务、角色边界与十四天共同协议</td></tr><tr><td>安放一天</td><td><a href="./daily-system">生活系统篇</a></td><td>三个容量版本、环境入口和关系边界</td></tr><tr><td>交给时间</td><td><a href="./rhythm-and-compounding">节律篇</a></td><td>可重复动作、回归协议和复查日期</td></tr></tbody></table><p>不要在第一周同时重建睡眠、学习、运动、工作和所有关系。只选择一个主问题。一个系统如果必须由五场同时进行的改革才能成立，就还没有准备好进入真实生活。</p><h2 id="读完留下什么" tabindex="-1">读完留下什么 <a class="header-anchor" href="#读完留下什么" aria-label="Permalink to &quot;读完留下什么&quot;">​</a></h2><p>这一部结束时，请留下：</p><ol><li>一页<a href="./../../templates/rhythm-ledger">节律账本</a>，记录容量、最小动作和阻力；若正在支持未成年学习者，再留一份<a href="./../../templates/family-learning-agreement">家庭学习共同协议</a>；</li><li>一次真实中断后的回归记录；</li><li>一个决定继续的设计，以及一个明确删除的要求；</li><li>一段可以保护的时间、一项可以说出口的边界和一个需要时能够联系的人。</li></ol><p>数字上升不是唯一结果。如果你更早看见疲惫，更少用熬夜偿还中断，更愿意求助，也更知道什么不值得继续，这些同样是系统变得可靠的证据。</p><h2 id="进入正文" tabindex="-1">进入正文 <a class="header-anchor" href="#进入正文" aria-label="Permalink to &quot;进入正文&quot;">​</a></h2><p>先不要设计理想的一年。把未来缩小到七天，让一个问题经过真实日程、不同容量和一次周末复查。</p><p>一周并不足以定义你，却足以告诉你下一周应该轻一点，还是清楚一点。</p>',18)])])}const f=a(i,[["render",l]]);export{m as __pageData,f as default};
